properties.query:
// Source: ArcSight — Brute Force Login
let lookback = ago(1h);
let threshold = 5;
SecurityEvents
| where TimeGenerated >= lookback
| where EventID == 4625
| summarize failures = count() by AccountName, IpAddress
| where failures > threshold
| join (SecurityEvent) on AccountName
| project AccountName, IpAddress, failures
